@Controller('countries')
export class CountriesController {
  // Selector for the country dropdown: the full list is fixed at ~250 rows,
  // so it is returned unpaginated. Bounded to MAX_SELECTOR_ROWS (500).
  @Get('selector')
  async selector() {
    return this.countries.findAll({ take: MAX_SELECTOR_ROWS });
  }
}

