// src/orders/orders.controller.ts
@Controller('orders')
export class OrdersController {
  // GET /orders
  @Get()
  async list(@Query() query: ListOrdersDto) {
    const orders = await this.orders.findPage(query.page, query.size);
    const rows = [];
    for (const order of orders.data) {
      // one query per order
      const customer = await this.db.customer.findUnique({ where: { id: order.customerId } });
      rows.push({ ...order, customerName: customer.name });
    }
    return { data: rows, meta: { page: query.page, pageSize: query.size, total: orders.total } };
  }

  // GET /orders/:id
  @Get(':id')
  async get(@Param('id') id: string) {
    return this.orders.findOne(id);
  }
}
```

The project documents list endpoints as returning an object with a data array and a meta object (page, pageSize, total).
